bool subset_sum(int i, int sum){
    if(i < 0) return sum == 0;   // nothing left to pick
    if(val[i] > sum) return subset_sum(i-1, sum);
    return subset_sum(i-1, sum - val[i])   // take it
        || subset_sum(i-1, sum);           // skip it
}

